"""Chapter 9 boss phase: the sortie target verifies the actual aim cell.

Owner 2026-11-16: from イデ！ a direct march at the moving boss's skull is
blocked by the cliffs, so the first leg aims at the waypoint north of the
castle (``navigation.boss_probe_cell``) and only a re-armed step aims at the
measured boss cell. ``_target_roof_under_marker`` used to verify every boss
landing against the bare boss cell, so a correct first-leg landing was
cancelled forever (``target_not_under_marker`` loop before any boss march).
"""
from docich.hanjuku_speedrun import hanjuku_chart as chart
from docich.hanjuku_speedrun.hanjuku.flows import map as M
from docich.hanjuku_speedrun.hanjuku.os_layer.navigation import boss_probe_cell
from docich.hanjuku_speedrun.hanjuku.os_layer.screen import Frame, Screen
from docich.hanjuku_speedrun.hanjuku.strategy import corridor

ORDER = {'step': 'A:t:Mboss', 'target': 'ボス', 'source': 'イデ！'}
FRAME = Frame(256, 224, b'\x00' * (256 * 224 * 3))
IDE = chart.castles(9)['イデ！']
WAYPOINT = chart.CH9_BOSS_WAYPOINT


def screen(cursor):
    return Screen([], None, '', kind='map_target', cursor=cursor)


def memory(cursor, **extra):
    return {'chapter': 9, 'tick': 10, 'cursor': list(cursor),
            'garrison': {}, **extra}


def test_the_first_leg_aims_at_the_waypoint_north_of_the_last_castle():
    assert boss_probe_cell(memory(WAYPOINT), 'ボス', ORDER['step']) == WAYPOINT


def test_a_first_leg_landing_on_the_waypoint_confirms():
    mem = memory(WAYPOINT)
    assert M._target_roof_under_marker(screen(WAYPOINT), mem, FRAME, ORDER) is True


def test_a_first_leg_landing_at_the_skull_itself_is_not_the_aim():
    chart.set_boss_cell(9, (826, 853))
    try:
        mem = memory((826, 853))
        assert M._target_roof_under_marker(screen((826, 853)), mem, FRAME, ORDER) is False
    finally:
        chart.set_boss_cell(9, None)


def test_the_pursuit_step_verifies_against_the_measured_boss_cell():
    # The second leg is the pursuit's (flows/boss_pursuit): its pseudo-step
    # aims and verifies at the measured boss cell. A castle order never skips
    # the first leg any more, whatever its relaunch counter says (ch9
    # 2026-11-17: counter-1 orders went straight at the skull and sat in the
    # pocket beside イデ！).
    chart.set_boss_cell(9, (826, 853))
    try:
        pursuit = {'step': 'PURSUIT', 'target': 'ボス', 'source': None}
        mem = memory((826, 853))
        assert M._target_roof_under_marker(screen((826, 853)), mem, FRAME, pursuit) is True
        rearmed = memory(WAYPOINT, boss_relaunch={ORDER['step']: 1})
        assert boss_probe_cell(rearmed, 'ボス', ORDER['step']) == WAYPOINT
    finally:
        chart.set_boss_cell(9, None)


def test_the_ch9_boss_cell_match_accepts_an_anchored_estimate():
    order = dict(ORDER)
    mem = memory(WAYPOINT)
    assert M._cell_match_evidence(screen(WAYPOINT), mem, order, FRAME) is True
    mem = memory(WAYPOINT, uncertain=True)
    assert M._cell_match_evidence(screen(WAYPOINT), mem, order, FRAME) is False


def _post_routes(front='イデ！'):
    return {front: [front], 'イソ': ['イソ', front], 'カラ': ['カラ', 'イソ', front]}


def _post_mem(**extra):
    return {'chapter': 9, 'tick': 10, 'captured': list(chart.corridor(9)),
            'world': {'sorties': {}}, **extra}


def test_the_boss_phase_posts_the_hero_at_the_front():
    wave = {'tick': 0}
    order = corridor._hero_post_order(_post_mem(), _post_routes(), 'イソ', wave)
    assert order is not None and order['target'] == 'イデ！' and order.get('corridor_hero')


def test_the_hero_already_at_the_front_stays():
    wave = {'tick': 0}
    assert corridor._hero_post_order(_post_mem(), _post_routes(), 'イデ！', wave) is None


def test_outside_the_boss_phase_the_post_stays_behind_the_front():
    mem = _post_mem(captured=list(chart.corridor(9)[:-1]))
    wave = {'tick': 0}
    # シマウ is three hops from イデ！: outside the boss phase it is the post.
    assert corridor._hero_post_order(mem, _post_routes(), 'シマウ', wave) is None
